      "path": "sim/axi_bc/run.py",
      "content": "#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1
"""Independent Verilator runner for the rv_iommu_axi_bc regression test.

Builds sim/axi_bc/axi_bc_tb.sv + sim/axi_bc/axi_bc_test.cpp together with the
DUT and its package dependencies using the classic object flow
(`verilator --cc --exe --build`, no --binary and no --timing) and then runs the
resulting test executable.

  python3 sim/axi_bc/run.py                        # full default suite
  python3 sim/axi_bc/run.py --focus fixed-tail     # one named legacy test
  python3 sim/axi_bc/run.py --out /tmp/ab_build    # explicit build directory
  python3 sim/axi_bc/run.py --source /path/to/repo # explicit repository root

The repository root defaults to the script's parents[2], i.e.
<root>/sim/axi_bc/run.py -> <root>.
"""

import argparse
import os
import shutil
import subprocess
import sys
from pathlib import Path

FOCUS_TESTS = ("fixed-tail", "incr-cross", "incr-byte-tail", "incr-unaligned")
EXE_NAME = "axi_bc_test"

SOURCES = (
    "sim/axi_bc/axi_bc_tb.sv",
    "sim/axi_bc/axi_bc_test.cpp",
    "rtl/transaction_controller/rv_iommu_axi_bc.sv",
    "vendor/axi/src/axi_pkg.sv",
    "vendor/common_cells/src/cf_math_pkg.sv",
)

INCLUDE_DIRS = (
    "vendor/axi/src",
    "vendor/common_cells/src",
    "rtl/transaction_controller",
)

# order: packages first, then the DUT, then the wrapper, then the C++ driver
VERILATOR_FILES = (SOURCES[3], SOURCES[4], SOURCES[2], SOURCES[0], SOURCES[1])

VERILATOR_ARGS = (
    "--cc",
    "--exe",
    "--build",
    "-sv",
    "--top-module",
    "axi_bc_tb",
    "-o",
    EXE_NAME,
    "-Wno-fatal",
    "-Wno-WIDTH",
    "-Wno-UNUSEDSIGNAL",
    "-Wno-UNUSEDPARAM",
    "-Wno-DECLFILENAME",
)


def repo_root():
    """<root>/sim/axi_bc/run.py -> <root>."""
    return Path(__file__).resolve().parents[2]


def find_exe(out_dir):
    """Locate the executable produced by `verilator --exe --build`."""
    exe = out_dir / EXE_NAME
    if exe.is_file():
        return exe
    candidates = sorted(
        p
        for p in out_dir.iterdir()
        if p.is_file() and p.suffix == "" and os.access(str(p), os.X_OK)
    )
    return candidates[0] if candidates else None


def build(root, out_dir, verilator, jobs):
    cmd = [verilator]
    cmd.extend(VERILATOR_ARGS)
    cmd.extend(["--Mdir", str(out_dir)])
    for inc in INCLUDE_DIRS:
        cmd.append("-I" + str(root / inc))
    if jobs:
        cmd.extend(["--build-jobs", str(jobs)])
    for rel in VERILATOR_FILES:
        cmd.append(str(root / rel))
    sys.stderr.write("run.py: " + " ".join(cmd) + "\n")
    return subprocess.run(cmd).returncode


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="run.py",
        description="Verilator regression runner for rv_iommu_axi_bc",
    )
    parser.add_argument(
        "--source",
        default=None,
        help="repository root containing rtl/ and vendor/ (default: <script>/../../)",
    )
    parser.add_argument(
        "--out",
        default=None,
        help="build directory (default: <root>/obj_dir_axi_bc)",
    )
    parser.add_argument(
        "--focus",
        action="append",
        default=[],
        metavar="NAME",
        help="run only this named case; repeatable or comma separated "
        "(" + ", ".join(FOCUS_TESTS) + ")",
    )
    parser.add_argument("--max-failures", type=int, default=16, help="printed failures (default 16)")
    parser.add_argument("--jobs", type=int, default=None, help="verilator --build-jobs")
    parser.add_argument("--clean", action="store_true", help="remove the build directory first")
    parser.add_argument("--no-build", action="store_true", help="reuse an existing executable")
    parser.add_argument("--list-tests", action="store_true", help="print the named cases and exit")
    parser.add_argument(
        "--verilator",
        default=os.environ.get("VERILATOR", "verilator"),
        help="verilator executable (default: $VERILATOR or 'verilator')",
    )
    args = parser.parse_args(argv)

    if args.list_tests:
        sys.stdout.write("\n".join(FOCUS_TESTS) + "\n")
        return 0

    root = Path(args.source).resolve() if args.source else repo_root()
    out_dir = Path(args.out).resolve() if args.out else root / "obj_dir_axi_bc"

    focus = []
    for item in args.focus or []:
        for name in str(item).split(","):
            name = name.strip()
            if not name:
                continue
            if name not in FOCUS_TESTS:
                sys.stderr.write(
                    "run.py: unknown focus test '{}' (known: {})\n".format(
                        name, ", ".join(FOCUS_TESTS)
                    )
                )
                return 2
            if name not in focus:
                focus.append(name)

    missing = [str(root / rel) for rel in SOURCES if not (root / rel).is_file()]
    if missing:
        sys.stderr.write("run.py: missing source files:\n  " + "\n  ".join(missing) + "\n")
        return 2

    verilator = shutil.which(args.verilator)
    if verilator is None and os.path.sep in args.verilator and os.access(args.verilator, os.X_OK):
        verilator = args.verilator
    if verilator is None:
        sys.stderr.write("run.py: verilator executable not found: {}\n".format(args.verilator))
        return 2

    if args.clean and out_dir.exists():
        shutil.rmtree(str(out_dir), ignore_errors=True)
    out_dir.mkdir(parents=True, exist_ok=True)

    ver = subprocess.run(
        [verilator, "--version"],
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        universal_newlines=True,
    )
    if ver.stdout:
        sys.stderr.write("run.py: " + ver.stdout.strip() + "\n")
    sys.stderr.write("run.py: build dir {}\n".format(out_dir))

    if not args.no_build:
        rc = build(root, out_dir, verilator, args.jobs)
        if rc != 0:
            sys.stderr.write("run.py: verilator build failed (rc={})\n".format(rc))
            return rc

    exe = find_exe(out_dir)
    if exe is None:
